		reasons = append(reasons, reason)
	}
	sort.Slice(reasons, func(i, j int) bool {
		if reasonTotals[reasons[i]] != reasonTotals[reasons[j]] {
			return reasonTotals[reasons[i]] > reasonTotals[reasons[j]]
		}
		return reasons[i] < reasons[j]
	})

